const page=document.querySelector('#detail-page'),toast=document.querySelector('#toast'),params=new URLSearchParams(location.search),id=params.get('id');
let communityState=null;
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(notify.t);notify.t=setTimeout(()=>toast.classList.remove('show'),3400)}
function heroImage(x){return x.image?`<img src="${esc(x.image)}" alt="Gambar ${esc(x.title)}">`:`<div class="detail-fallback ${NMData.coverClass(x.category)}"><span>${esc(x.category)}</span><b>${esc(x.title)}</b></div>`}
function shortDescription(value='',limit=320){const text=String(value).replace(/^DESKRIPSI MOD\s*/i,'').trim();if(text.length<=limit)return text;const cut=text.slice(0,limit),lastSpace=cut.lastIndexOf(' ');return`${cut.slice(0,lastSpace>limit*.7?lastSpace:limit).trim()}…`}
function fileEntries(item){return[{label:item.downloadLabel||`File utama — ${item.title}`,url:item.link},...(item.downloadLinks||[])].filter(file=>String(file.url||'').trim())}
function fileInventory(item){const files=fileEntries(item);return `<section class="file-inventory"><div class="file-inventory-heading"><div><span>Isi unduhan</span><h3>${files.length} file tersedia</h3></div><b>${files.length}</b></div>${files.length?`<ul>${files.map((file,index)=>`<li><span>${String(index+1).padStart(2,'0')}</span><div><b>${esc(file.label||`File ${index+1}`)}</b><small>${index===0?'File utama':'File pendukung'}</small></div></li>`).join('')}</ul>`:'<p>Belum ada file unduhan yang dicantumkan.</p>'}</section>`}
function installationSteps(item){const custom=String(item.installInstructions||'').split(/\r?\n/).map(step=>step.trim()).filter(Boolean),steps=custom.length?custom:['Periksa versi game dan kompatibilitas.','Cadangkan file game atau data simpanan.','Unduh semua file yang tercantum.','Ikuti tutorial video dan aktifkan mod.'];return steps.map(step=>`<li>${esc(step)}</li>`).join('')}
function tutorial(x){const youtubeId=NMData.youtubeId(x.youtube);if(!youtubeId)return`<div class="video-empty"><span>▶</span><h3>Tutorial belum tersedia</h3><p>Admin belum menambahkan URL video YouTube untuk mod ini.</p></div>`;const watchUrl=`https://www.youtube.com/watch?v=${youtubeId}`;return`<div class="video-shell"><div class="video-frame youtube-facade" data-youtube-id="${youtubeId}" data-video-title="Tutorial pemasangan ${esc(x.title)}"><img src="https://i.ytimg.com/vi/${youtubeId}/maxresdefault.jpg" data-thumb-step="0" alt="Thumbnail tutorial ${esc(x.title)}" loading="lazy"><button type="button" class="youtube-play" aria-label="Putar tutorial ${esc(x.title)}"><span>▶</span></button><div class="youtube-facade-title">${esc(x.title)}</div></div></div><div class="video-actions"><span>Klik thumbnail untuk memutar video di halaman ini.</span><a href="${watchUrl}" target="_blank" rel="noopener">Tonton di YouTube ↗</a></div>`}
let youtubeApiPromise;
function loadYoutubeApi(){if(window.YT?.Player)return Promise.resolve(window.YT);if(youtubeApiPromise)return youtubeApiPromise;youtubeApiPromise=new Promise((resolve,reject)=>{const previous=window.onYouTubeIframeAPIReady;window.onYouTubeIframeAPIReady=()=>{if(typeof previous==='function')previous();resolve(window.YT)};const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.async=true;script.onerror=()=>reject(new Error('YouTube Player API gagal dimuat.'));document.head.append(script)});return youtubeApiPromise}
function bindTutorialPlayer(){const host=document.querySelector('.youtube-facade');if(!host)return;const image=host.querySelector('img');image.addEventListener('error',()=>{const step=Number(image.dataset.thumbStep||0);if(step===0){image.dataset.thumbStep='1';image.src=`https://i.ytimg.com/vi/${host.dataset.youtubeId}/sddefault.jpg`}else if(step===1){image.dataset.thumbStep='2';image.src=`https://i.ytimg.com/vi/${host.dataset.youtubeId}/hqdefault.jpg`}});host.querySelector('.youtube-play').addEventListener('click',async()=>{const youtubeId=host.dataset.youtubeId,title=host.dataset.videoTitle||'Tutorial YouTube';host.classList.remove('youtube-facade');host.innerHTML='<div class="youtube-player-target"></div>';try{const YT=await loadYoutubeApi();new YT.Player(host.querySelector('.youtube-player-target'),{width:'100%',height:'100%',videoId:youtubeId,playerVars:{autoplay:1,controls:1,playsinline:1,rel:0,origin:location.origin},events:{onReady:event=>{const iframe=event.target.getIframe();iframe.title=title;iframe.referrerPolicy='strict-origin-when-cross-origin';event.target.playVideo()}}})}catch(error){host.innerHTML='<div class="video-empty"><span>!</span><h3>Player gagal dimuat</h3><p>Gunakan tombol Tonton di YouTube di bawah.</p></div>'}})}
function notFound(message='Item mungkin dinonaktifkan atau sudah dihapus dari katalog.'){document.title='Mod tidak ditemukan — Nusantara Mod';page.innerHTML=`<section class="not-found"><span class="eyebrow"><i></i> 404</span><h1>Mod tidak ditemukan</h1><p>${esc(message)}</p><a class="button primary" href="index.html#koleksi">Kembali ke katalog</a></section>`}
function ratingStars(){return[1,2,3,4,5].map(value=>`<button type="button" data-rate="${value}" aria-label="Beri rating ${value} bintang">★</button>`).join('')}
function communityMarkup(){return `<section class="community-section" id="komentar"><div class="community-heading"><div><span class="eyebrow"><i></i> Komunitas pemain</span><h2>Komentar pemain</h2></div><p>Masuk untuk memberi satu rating dan berbagi pengalaman dengan pemain lain.</p></div><div class="community-layout"><div class="community-compose"><div class="community-login" id="community-login"><h3>Masuk untuk bergabung</h3><p>Gunakan akun Google atau tautan aman melalui email apa pun.</p><button class="button google-button" id="google-login" type="button"><b>G</b> Lanjutkan dengan Google</button><div class="login-divider"><span>atau</span></div><form id="email-login-form"><label>Email<input id="community-email" type="email" required placeholder="nama@email.com"></label><button class="button ghost wide" type="submit">Kirim tautan masuk</button></form></div><div class="community-user" id="community-user" hidden></div><form class="comment-form" id="comment-form" hidden><label>Tulis komentar<textarea id="comment-body" required minlength="2" maxlength="800" rows="5" placeholder="Ceritakan pengalamanmu menggunakan mod ini..."></textarea></label><div><small>Maksimal 800 karakter.</small><button class="button primary" type="submit">Kirim komentar</button></div></form></div><div class="comment-feed"><div class="comment-feed-title"><h3>Komentar terbaru</h3><span id="comment-count">0 komentar</span></div><div id="comment-list"><p class="community-muted">Memuat komentar…</p></div></div></div></section>`}
function render(item){const detailCopy=item.details?`<div class="detail-rich-copy">${esc(item.details)}</div>`:'<div class="detail-empty-copy"><b>Rincian tambahan belum tersedia</b><p>Admin dapat mengisi fitur, perubahan, kompatibilitas, dan isi paket melalui editor katalog.</p></div>',intro=shortDescription(item.description);document.title=`${item.title} — Nusantara Mod`;page.innerHTML=`<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="index.html">Beranda</a><span>›</span><a href="index.html#koleksi">Koleksi</a><span>›</span><b>${esc(item.title)}</b></nav>
  <section class="detail-hero"><header class="detail-title-band"><div><span class="eyebrow"><i></i> ${esc(item.category)} · ${esc(item.platform)}</span><h1>${esc(item.title)}</h1></div><div class="detail-badges"><span id="detail-rating">★ ${esc(item.rating||'Baru')}</span><span>${esc(item.version)}</span><span>${esc(item.size)}</span></div></header><div class="detail-cover">${heroImage(item)}</div><div class="detail-summary"><span class="detail-summary-label">Ringkasan mod</span><p class="detail-lead">${esc(intro)}</p><div class="creator-credit"><span>Dibuat / dipublikasikan oleh</span><b>${esc(item.creator||'Nusantara Mod')}</b></div><a class="button primary detail-cta" href="#download">Lihat tutorial & download <span>↓</span></a></div></section>
  <section class="detail-content"><article class="detail-article"><span class="eyebrow"><i></i> Rincian mod</span><h2>Fitur & isi paket</h2>${detailCopy}${fileInventory(item)}<div class="spec-grid"><div><span>Versi</span><b>${esc(item.version)}</b></div><div><span>Ukuran file</span><b>${esc(item.size)}</b></div><div><span>Platform</span><b>${esc(item.platform)}</b></div><div><span>Kategori</span><b>${esc(item.category)}</b></div></div><div class="safety-note"><b>Catatan keamanan</b><p>Unduh hanya dari sumber yang dicantumkan. Pindai file dan cadangkan data permainan sebelum memasang mod.</p></div></article><aside class="detail-side install-guide"><span>Cara instal</span><h3>Urutan pemasangan</h3><ol>${installationSteps(item)}</ol></aside></section>
  <div class="page-ad detail-page-ad" id="detail-page-ad" aria-label="Iklan halaman detail"></div>
  <section class="tutorial-section" id="tutorial"><div class="section-heading"><div><span class="eyebrow"><i></i> Panduan video</span><h2>Cara pemasangan</h2></div><p>Tonton sampai selesai sebelum mengubah file permainan.</p></div>${tutorial(item)}</section>
  <section class="download-panel" id="download"><div><span class="eyebrow light"><i></i> Siap memasang?</span><h2>Download ${esc(item.title)}</h2><p>Baca tips singkat dan tunggu link sumber disiapkan.</p></div><div class="download-actions"><a class="button light-button" href="download.html?id=${encodeURIComponent(item.id)}">Siapkan link download <span>→</span></a><div class="rating-mini"><span>Rating pemain</span><div class="rating-stars" id="rating-stars">${ratingStars()}</div><small id="rating-summary">Belum ada rating</small></div></div></section>${communityMarkup()}`}

async function loadDetailAd(){const host=document.querySelector('#detail-page-ad');try{const settings=await NMData.getSettings();window.NMAds?.renderPageAd(host,settings.ads?.detail);bindDownloadClickAd(settings.downloadClickAd)}catch{if(host)host.hidden=true}}

function profileOf(comment){const value=comment.profiles;return Array.isArray(value)?value[0]||{}:value||{}}
function commentTree(comments){const nodes=new Map(comments.map(comment=>[comment.id,{...comment,replies:[]}])),roots=[];nodes.forEach(comment=>{const parent=comment.parent_id&&nodes.get(comment.parent_id);if(parent&&parent.id!==comment.id)parent.replies.push(comment);else roots.push(comment)});roots.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));nodes.forEach(comment=>comment.replies.sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)));return roots}
function commentCard(comment,user,seen=new Set()){if(seen.has(comment.id))return'';const branch=new Set(seen).add(comment.id),profile=profileOf(comment),name=profile.display_name||'Pengguna',initial=String(name).charAt(0).toUpperCase(),avatar=profile.avatar_url?`<img src="${esc(profile.avatar_url)}" alt="">`:`<span>${esc(initial)}</span>`,own=user?.id===comment.user_id,replies=(comment.replies||[]).map(reply=>commentCard(reply,user,branch)).join('');return `<div class="comment-thread"><article class="comment-card" data-comment-id="${comment.id}"><div class="comment-avatar">${avatar}</div><div><div class="comment-meta"><b>${esc(name)}</b><time>${new Date(comment.created_at).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}</time></div><p>${esc(comment.body)}</p><div class="comment-actions"><button type="button" data-reply-comment="${comment.id}" data-reply-name="${esc(name)}">Balas</button>${own?`<button type="button" data-delete-comment="${comment.id}">Hapus</button>`:''}</div><div class="reply-slot"></div></div></article>${replies?`<div class="comment-replies">${replies}</div>`:''}</div>`}
function renderCommunity(state){communityState=state;const stars=[...document.querySelectorAll('[data-rate]')];stars.forEach(button=>button.classList.toggle('active',Number(button.dataset.rate)<=state.userRating));document.querySelector('#rating-summary').textContent=state.count?`${state.average.toFixed(1)} dari 5 · ${state.count} suara`:'Belum ada rating';const detailRating=document.querySelector('#detail-rating');if(detailRating)detailRating.textContent=state.count?`★ ${state.average.toFixed(1)} · ${state.count} suara`:'★ Baru';const login=document.querySelector('#community-login'),userBox=document.querySelector('#community-user'),form=document.querySelector('#comment-form');if(state.user){const meta=state.user.user_metadata||{},name=meta.full_name||meta.name||state.user.email?.split('@')[0]||'Pengguna';login.hidden=true;userBox.hidden=false;userBox.innerHTML=`<div><b>${esc(name)}</b><span>Login sebagai anggota komunitas</span></div><button type="button" id="community-logout">Keluar</button>`;form.hidden=false}else{login.hidden=false;userBox.hidden=true;form.hidden=true}document.querySelector('#comment-count').textContent=`${state.comments.length} komentar`;document.querySelector('#comment-list').innerHTML=state.comments.length?commentTree(state.comments).map(comment=>commentCard(comment,state.user)).join(''):'<div class="comment-empty"><span>✦</span><p>Belum ada komentar. Jadilah yang pertama.</p></div>'}
async function loadCommunity(){try{renderCommunity(await NMData.getCommunity(id))}catch(error){document.querySelector('#comment-list').innerHTML='<p class="community-muted">Fitur komentar belum aktif. Jalankan skrip komunitas di Supabase.</p>';document.querySelector('#rating-summary').textContent='Belum aktif'}}
function requireUser(){if(communityState?.user)return true;document.querySelector('#community-login').scrollIntoView({behavior:'smooth',block:'center'});notify('Silakan login untuk memberi rating atau komentar.');return false}
function bindCommunity(){document.querySelector('#rating-stars').addEventListener('click',async e=>{const button=e.target.closest('[data-rate]');if(!button||!requireUser())return;try{await NMData.saveRating(id,Number(button.dataset.rate));await loadCommunity();notify('Rating kamu sudah disimpan.')}catch(error){notify(error.message||'Rating gagal disimpan.')}});document.querySelector('#google-login').addEventListener('click',async()=>{try{await NMData.signInGoogle()}catch(error){notify(error.message||'Login Google belum tersedia.')}});document.querySelector('#email-login-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await NMData.signInEmail(document.querySelector('#community-email').value.trim());notify('Tautan masuk sudah dikirim. Periksa kotak masuk email.')}catch(error){notify(error.message||'Tautan masuk gagal dikirim.')}finally{button.disabled=false}});document.querySelector('#comment-form').addEventListener('submit',async e=>{e.preventDefault();if(!requireUser())return;const button=e.submitter,body=document.querySelector('#comment-body').value.trim();button.disabled=true;try{await NMData.addComment(id,body);document.querySelector('#comment-body').value='';await loadCommunity();notify('Komentar berhasil dikirim.')}catch(error){notify(error.message||'Komentar gagal dikirim.')}finally{button.disabled=false}});document.querySelector('#komentar').addEventListener('submit',async e=>{const replyForm=e.target.closest('.reply-form');if(!replyForm)return;e.preventDefault();if(!requireUser())return;const button=e.submitter,body=replyForm.querySelector('textarea').value.trim();button.disabled=true;try{await NMData.addComment(id,body,replyForm.dataset.parentId);await loadCommunity();notify('Balasan berhasil dikirim.')}catch(error){notify(error.message||'Balasan gagal dikirim.')}finally{button.disabled=false}});document.querySelector('#komentar').addEventListener('click',async e=>{if(e.target.id==='community-logout'){await NMData.signOut();await loadCommunity();notify('Kamu sudah keluar.');return}const reply=e.target.closest('[data-reply-comment]');if(reply){if(!requireUser())return;document.querySelectorAll('.reply-slot').forEach(slot=>slot.innerHTML='');const slot=reply.closest('.comment-card').querySelector('.reply-slot');slot.innerHTML=`<form class="reply-form" data-parent-id="${reply.dataset.replyComment}"><label>Balas ${esc(reply.dataset.replyName)}<textarea required minlength="2" maxlength="800" rows="3" placeholder="Tulis balasanmu..."></textarea></label><div><button type="button" data-cancel-reply>Batal</button><button class="button primary" type="submit">Kirim balasan</button></div></form>`;slot.querySelector('textarea').focus();return}if(e.target.closest('[data-cancel-reply]')){e.target.closest('.reply-slot').innerHTML='';return}const del=e.target.closest('[data-delete-comment]');if(del&&confirm('Hapus komentar ini beserta semua balasannya?')){try{await NMData.deleteComment(del.dataset.deleteComment);await loadCommunity();notify('Komentar dihapus.')}catch(error){notify(error.message||'Komentar gagal dihapus.')}}})}

document.querySelector('#year').textContent=new Date().getFullYear();
(async()=>{if(!id)return notFound();try{const item=await NMData.getMod(id);if(!item)return notFound();render(item);bindTutorialPlayer();bindCommunity();await Promise.all([loadCommunity(),loadDetailAd()])}catch(error){notFound('Data mod belum dapat dimuat. Periksa koneksi lalu coba lagi.')}})();
function bindDownloadClickAd(config){
  if(!config?.active)return;
  let url;try{url=new URL(config.url)}catch{return}
  if(url.protocol!=='https:'||url.username||url.password)return;
  const link=document.querySelector('#download .download-actions a');
  if(!link)return;
  const ad=document.createElement('a');
  ad.href=url.href;ad.target='_blank';ad.rel='noopener noreferrer sponsored';
  ad.textContent='Iklan: buka di tab baru ↗';
  link.insertAdjacentElement('afterend',ad);
}
